package org.jkiss.dbeaver.teststudio.ai;
import com.google.gson.*;import java.util.Locale;import org.jkiss.dbeaver.teststudio.spi.TestStudioAiProvider;
public final class HeuristicAiProvider implements TestStudioAiProvider{public String id(){return "heuristic-safe-template";}public JsonObject capabilities(){JsonObject r=new JsonObject();r.addProperty("network",false);r.addProperty("deterministic",true);r.addProperty("generate_plan",true);r.addProperty("improve_plan",true);r.addProperty("analyze_failure",true);r.addProperty("note","Safe offline fallback; external AI providers may contribute richer generation");return r;}public JsonObject generatePlan(String prompt,JsonObject context){String project=str(context,"project","General");String connection=str(context,"connection","CHANGE_ME");String id=slug(prompt);JsonObject plan=new JsonObject();plan.addProperty("schema_version","1.0");plan.addProperty("id",id);plan.addProperty("name",prompt.isBlank()?"Generated database test":trim(prompt,200));JsonObject target=new JsonObject();target.addProperty("connection",connection);target.addProperty("project",project);JsonObject targets=new JsonObject();targets.add("default",target);plan.add("targets",targets);plan.add("variables",new JsonObject());plan.add("setup",new JsonArray());JsonArray steps=new JsonArray();JsonObject step=new JsonObject();step.addProperty("id","health-check");step.addProperty("type","query");step.addProperty("target","default");step.addProperty("sql",suggestSql(prompt));JsonArray assertions=new JsonArray();JsonObject assertion=new JsonObject();assertion.addProperty("type","row_count");assertion.addProperty("expected",1);assertions.add(assertion);step.add("assertions",assertions);steps.add(step);plan.add("steps",steps);plan.add("cleanup",new JsonArray());JsonObject policy=new JsonObject();policy.addProperty("sandbox","read_only");plan.add("policy",policy);JsonArray assumptions=new JsonArray();assumptions.add("Connection and SQL are placeholders until schema-aware context is supplied.");JsonObject result=new JsonObject();result.add("plan",plan);result.add("assumptions",assumptions);result.addProperty("provider",id());result.addProperty("requires_review",true);return result;}public JsonObject improvePlan(JsonObject plan,String request,JsonObject context){JsonObject copy=plan.deepCopy();copy.addProperty("updated_at",java.time.Instant.now().toString());JsonArray notes=copy.has("ai_notes")&&copy.get("ai_notes").isJsonArray()?copy.getAsJsonArray("ai_notes"):new JsonArray();notes.add(trim(request,1000));copy.add("ai_notes",notes);JsonObject result=new JsonObject();result.add("plan",copy);result.addProperty("provider",id());result.addProperty("requires_review",true);return result;}public JsonObject analyzeFailure(JsonObject run,JsonObject context){JsonObject result=new JsonObject();result.addProperty("provider",id());result.addProperty("probable_cause",run.has("error")?"Runner or database operation failed":"One or more assertions did not match observed evidence");result.addProperty("confidence",0.35);JsonArray checks=new JsonArray();checks.add("Inspect the first failed step and its bounded evidence.");checks.add("Verify target connection, fixture setup, and cleanup status.");checks.add("Compare the run with the latest passing baseline.");result.add("next_checks",checks);result.addProperty("official_result",false);return result;}private static String suggestSql(String p){String s=p.toLowerCase(Locale.ENGLISH);if(s.contains("version"))return "SELECT version() AS database_version";if(s.contains("time")||s.contains("clock"))return "SELECT CURRENT_TIMESTAMP AS database_time";return "SELECT 1 AS ok";}private static String slug(String p){String s=p.toLowerCase(Locale.ENGLISH).replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");if(s.isBlank())s="generated-test";return s.substring(0,Math.min(80,s.length()));}private static String str(JsonObject o,String k,String d){return o.has(k)&&o.get(k).isJsonPrimitive()?o.get(k).getAsString():d;}private static String trim(String s,int n){return s.length()<=n?s:s.substring(0,n);}}
